import type { PriceLevel } from '../types';

/**
 * Buckets fine-grained price levels into coarser ticks for ladder display.
 * Bids round DOWN to the nearest tick (never overstate what a buyer is
 * willing to pay); asks round UP (never understate what a seller wants).
 * Quantity is conserved: the sum of qty before and after bucketing matches.
 */
export function groupLevelsByTick(levels: PriceLevel[], tickSize: number, side: 'bid' | 'ask'): PriceLevel[] {
  const buckets = new Map<number, number>();

  for (const level of levels) {
    const ticks = level.price / tickSize;
    const roundedTicks = side === 'bid' ? Math.floor(ticks + 1e-9) : Math.ceil(ticks - 1e-9);
    // Round the bucket price itself to avoid floating point drift (e.g. 0.1 + 0.2 issues).
    const bucketPrice = roundToTickPrecision(roundedTicks * tickSize, tickSize);
    buckets.set(bucketPrice, (buckets.get(bucketPrice) ?? 0) + level.qty);
  }

  const result: PriceLevel[] = Array.from(buckets.entries()).map(([price, qty]) => ({ price, qty }));
  result.sort((a, b) => (side === 'bid' ? b.price - a.price : a.price - b.price));
  return result;
}

/** Rounds a bucketed price to the decimal precision implied by tickSize, to avoid FP noise like 100.00000000001. */
function roundToTickPrecision(value: number, tickSize: number): number {
  const decimals = Math.max(0, decimalPlaces(tickSize));
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

function decimalPlaces(n: number): number {
  const s = n.toString();
  if (s.includes('e-')) {
    // Handle very small tick sizes expressed in exponential notation.
    const [, exp] = s.split('e-');
    return Number(exp);
  }
  const idx = s.indexOf('.');
  return idx === -1 ? 0 : s.length - idx - 1;
}

export interface LevelWithCumulative extends PriceLevel {
  cumulative: number;
}

/** Running total of qty in the given (already-sorted) order, for depth-bar rendering. */
export function withCumulative(levels: PriceLevel[]): LevelWithCumulative[] {
  let running = 0;
  const result: LevelWithCumulative[] = [];
  for (const level of levels) {
    running += level.qty;
    result.push({ ...level, cumulative: running });
  }
  return result;
}

export function computeMidPrice(bestBid: number | null, bestAsk: number | null): number | null {
  if (bestBid === null || bestAsk === null) return null;
  return (bestBid + bestAsk) / 2;
}

import type { AggTradeEvent, TradeTapeEntry } from '../types';

/**
 * Maps a raw Binance aggTrade event to a display-ready tape entry.
 * Per Binance's docs, `m === true` means the buyer was the market maker,
 * i.e. this print was triggered by an aggressive SELL (taker sold into the
 * bid); `m === false` means the taker bought (lifted the ask).
 */
export function classifyTrade(evt: AggTradeEvent, largeNotionalThreshold: number): TradeTapeEntry {
  const price = Number(evt.p);
  const qty = Number(evt.q);
  const notional = price * qty;
  return {
    id: evt.a,
    symbol: evt.s,
    price,
    qty,
    notional,
    side: evt.m ? 'sell' : 'buy',
    time: evt.T,
    isLarge: notional >= largeNotionalThreshold,
  };
}

/** Fixed-capacity ring buffer for the trade tape; newest entry first. */
export class TapeBuffer {
  private readonly maxLength: number;
  private buffer: TradeTapeEntry[] = [];

  constructor(maxLength: number) {
    if (maxLength <= 0) {
      throw new Error(`TapeBuffer maxLength must be positive, got ${maxLength}`);
    }
    this.maxLength = maxLength;
  }

  push(entry: TradeTapeEntry): void {
    this.buffer.unshift(entry);
    if (this.buffer.length > this.maxLength) {
      this.buffer.length = this.maxLength;
    }
  }

  get entries(): TradeTapeEntry[] {
    return this.buffer;
  }
}

import type { Candle, KlineEvent, KlineInterval } from '../types';

const INTERVAL_MS: Record<KlineInterval, number> = {
  '1m': 60_000,
  '3m': 3 * 60_000,
  '5m': 5 * 60_000,
  '15m': 15 * 60_000,
  '30m': 30 * 60_000,
  '1h': 3_600_000,
  '2h': 2 * 3_600_000,
  '4h': 4 * 3_600_000,
  '6h': 6 * 3_600_000,
  '12h': 12 * 3_600_000,
  '1d': 24 * 3_600_000,
  '3d': 3 * 24 * 3_600_000,
  '1w': 7 * 24 * 3_600_000,
};

/** Start-of-bucket epoch ms for the interval containing timeMs (UTC-aligned). */
export function bucketStart(timeMs: number, interval: KlineInterval): number {
  const span = INTERVAL_MS[interval];
  return Math.floor(timeMs / span) * span;
}

/** Maps a raw kline stream event to a numeric Candle, ignoring out-of-order/older events. */
export function applyKlineEvent(current: Candle | null, evt: KlineEvent): Candle {
  const { k } = evt;
  const incoming: Candle = {
    openTime: k.t,
    closeTime: k.T,
    open: Number(k.o),
    high: Number(k.h),
    low: Number(k.l),
    close: Number(k.c),
    volume: Number(k.v),
    closed: k.x,
  };

  // If this event belongs to a different (newer) bar than `current`, it's a fresh candle - use it as-is.
  if (!current || current.openTime !== incoming.openTime) {
    return incoming;
  }

  // Same bar: guard against a stale/duplicate/out-of-order event regressing already-observed
  // high/low/volume/closed state. Merge conservatively rather than blindly overwriting.
  return {
    openTime: current.openTime,
    closeTime: incoming.closeTime,
    open: current.open,
    high: Math.max(current.high, incoming.high),
    low: Math.min(current.low, incoming.low),
    close: incoming.close,
    volume: Math.max(current.volume, incoming.volume),
    closed: current.closed || incoming.closed,
  };
}

/** Merges a live-updating candle into REST-fetched history without duplicating the in-progress bar. */
export function mergeHistory(history: Candle[], latest: Candle): Candle[] {
  if (history.length === 0) return [latest];
  const last = history[history.length - 1];
  if (last.openTime === latest.openTime) {
    return [...history.slice(0, -1), latest];
  }
  return [...history, latest];
}

import type { MiniTickerEvent, WatchlistRow } from '../types';

/** Maps a raw 24hr mini-ticker event to a display-ready watchlist row. */
export function applyMiniTicker(evt: MiniTickerEvent): WatchlistRow {
  const open = Number(evt.o);
  const close = Number(evt.c);
  return {
    symbol: evt.s,
    last: close,
    changePct: ((close - open) / open) * 100,
    high: Number(evt.h),
    low: Number(evt.l),
    quoteVolume: Number(evt.q),
    updatedAt: evt.E,
  };
}

export type WatchlistSortKey = 'symbol' | 'changePct' | 'quoteVolume';

/** Returns a new, sorted array; never mutates the input. */
export function sortWatchlist(rows: WatchlistRow[], by: WatchlistSortKey, dir: 'asc' | 'desc'): WatchlistRow[] {
  const sign = dir === 'asc' ? 1 : -1;
  return [...rows].sort((a, b) => {
    const av = a[by];
    const bv = b[by];
    if (typeof av === 'string' && typeof bv === 'string') {
      return av.localeCompare(bv) * sign;
    }
    return ((av as number) - (bv as number)) * sign;
  });
}

import { useEffect, useRef } from 'react';
import type { ConnectionStatus } from '../core/hub/protocol';
import type { OrderBookStatus } from '../core/types';

/**
 * Unified visible status for a panel's status badge. Distinct from the raw
 * hub-level `ConnectionStatus` and per-stream statuses (e.g.
 * `OrderBookStatus`) - this is what the UI actually shows, folding both
 * "is the socket connected" and "is data still flowing for THIS panel" into
 * one of four states.
 */
export type PanelStatus = 'live' | 'stale' | 'reconnecting' | 'offline';

/** Order book panels get an explicit per-symbol status straight from the hub. */
export function deriveOrderBookStatus(connection: ConnectionStatus, bookStatus: OrderBookStatus): PanelStatus {
  if (connection === 'offline') return 'offline';
  if (connection === 'reconnecting' || connection === 'connecting') return 'reconnecting';
  switch (bookStatus) {
    case 'live':
      return 'live';
    case 'stale':
      return 'stale';
    case 'resyncing':
    case 'syncing':
    case 'uninitialized':
    default:
      return 'reconnecting';
  }
}

/**
 * Trade tape / candlestick / watchlist streams don't carry an explicit
 * per-message status - we infer "stale" from how long it's been since the
 * last message arrived while the hub connection itself reports live.
 */
export function deriveStreamStatus(
  connection: ConnectionStatus,
  lastUpdateAt: number | null,
  now: number,
  staleAfterMs = 8000,
): PanelStatus {
  if (connection === 'offline') return 'offline';
  if (connection === 'reconnecting' || connection === 'connecting') return 'reconnecting';
  if (lastUpdateAt === null) return 'reconnecting'; // connected but no first message yet
  return now - lastUpdateAt > staleAfterMs ? 'stale' : 'live';
}

/**
 * Runs `check` on an interval in addition to whatever event-driven calls the
 * caller makes. Needed because staleness (no message for N seconds) is only
 * detectable by the *absence* of an event, so something has to poll a clock.
 * Kept to a slow cadence (default 2s) - this is status-badge bookkeeping,
 * not per-tick rendering, so it's fine to use a plain interval + setState.
 */
export function usePeriodicCheck(check: () => void, intervalMs = 2000): void {
  const checkRef = useRef(check);
  checkRef.current = check;

  useEffect(() => {
    const id = window.setInterval(() => checkRef.current(), intervalMs);
    return () => window.clearInterval(id);
  }, [intervalMs]);
}

import { useCallback, useState } from 'react';
import { useLinkedSymbol } from '../workspace/LinkGroupContext';
import type { PanelInstanceConfig } from './PanelProps';

export const LINK_GROUPS: ReadonlyArray<{ value: string | null; label: string }> = [
  { value: null, label: 'None' },
  { value: 'A', label: 'Group A' },
  { value: 'B', label: 'Group B' },
  { value: 'C', label: 'Group C' },
  { value: 'D', label: 'Group D' },
];

/**
 * Glue between a panel's `PanelProps` contract and the cross-window
 * link-group bus (`useLinkedSymbol`).
 *
 * NOTE / known contract gap: `PanelProps` exposes `onSymbolChange` but has
 * no dedicated callback for changing a panel's `linkGroup`. The PRD asks
 * every panel chrome to offer a None/A/B/C/D link-group selector, so this
 * hook tracks the active link group as local component state (seeded from
 * `config.linkGroup`) and best-effort persists a change through
 * `onSettingsChange({ ...settings, linkGroup })`. That makes the selector
 * fully functional for live symbol-linking in the current session; whether
 * the workspace/layout layer reads `settings.linkGroup` back into
 * `config.linkGroup` on the next load is outside this panel package's
 * scope (see final report).
 */
export function usePanelLink(
  config: PanelInstanceConfig,
  onSymbolChange: (symbol: string) => void,
  onSettingsChange: (settings: Record<string, unknown>) => void,
  fallbackSymbol: string,
): {
  symbol: string;
  linkGroup: string | null;
  handleSymbolChange: (symbol: string) => void;
  handleLinkGroupChange: (group: string | null) => void;
} {
  const [linkGroup, setLinkGroupState] = useState<string | null>(config.linkGroup);
  const [symbol, setLinkedSymbol] = useLinkedSymbol(linkGroup, config.symbols[0] ?? fallbackSymbol);

  const handleSymbolChange = useCallback(
    (next: string) => {
      setLinkedSymbol(next);
      onSymbolChange(next);
    },
    [setLinkedSymbol, onSymbolChange],
  );

  const handleLinkGroupChange = useCallback(
    (next: string | null) => {
      setLinkGroupState(next);
      onSettingsChange({ ...config.settings, linkGroup: next });
    },
    [config.settings, onSettingsChange],
  );

  return { symbol, linkGroup, handleSymbolChange, handleLinkGroupChange };
}

import { useEffect, useState, type ReactNode } from 'react';
import styles from './PanelChrome.module.css';
import { LINK_GROUPS } from './usePanelLink';
import type { PanelStatus } from './panelStatus';

const STATUS_LABEL: Record<PanelStatus, string> = {
  live: 'Live',
  stale: 'Stale',
  reconnecting: 'Reconnecting',
  offline: 'Offline',
};

interface PanelChromeProps {
  title: string;
  symbol: string;
  onSymbolChange: (symbol: string) => void;
  linkGroup: string | null;
  onLinkGroupChange: (group: string | null) => void;
  status: PanelStatus;
  children: ReactNode;
}

/**
 * Shared header/wrapper rendered by every panel kind: title, an editable
 * symbol field, a link-group selector, and a connection/data status badge.
 * Keeping this in one place means every panel looks and behaves
 * consistently and only has to pass in its own symbol/status state.
 */
export default function PanelChrome({
  title,
  symbol,
  onSymbolChange,
  linkGroup,
  onLinkGroupChange,
  status,
  children,
}: PanelChromeProps) {
  const [draftSymbol, setDraftSymbol] = useState(symbol);

  // Keep the text field in sync when the symbol changes from elsewhere
  // (link-group broadcast from another panel/window, watchlist click, etc.)
  useEffect(() => {
    setDraftSymbol(symbol);
  }, [symbol]);

  const commitSymbol = () => {
    const next = draftSymbol.trim().toUpperCase();
    if (next && next !== symbol) {
      onSymbolChange(next);
    }
    setDraftSymbol(next || symbol);
  };

  return (
    <div className={styles.chrome}>
      <div className={styles.header}>
        <span className={styles.title}>{title}</span>
        <input
          className={styles.symbolInput}
          value={draftSymbol}
          onChange={(e) => setDraftSymbol(e.target.value)}
          onBlur={commitSymbol}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              commitSymbol();
              e.currentTarget.blur();
            }
          }}
          aria-label="Symbol"
          spellCheck={false}
        />
        <select
          className={styles.linkSelect}
          value={linkGroup ?? ''}
          onChange={(e) => onLinkGroupChange(e.target.value === '' ? null : e.target.value)}
          aria-label="Link group"
          title="Link group"
        >
          {LINK_GROUPS.map((g) => (
            <option key={g.label} value={g.value ?? ''}>
              {g.label}
            </option>
          ))}
        </select>
        <span className={`${styles.statusBadge} ${styles[status]}`} role="status" aria-label={`Status: ${STATUS_LABEL[status]}`}>
          <span className={styles.statusDot} />
          {STATUS_LABEL[status]}
        </span>
      </div>
      <div className={styles.body}>{children}</div>
      <div className={styles.footer}>Data: Binance Spot (public market data)</div>
    </div>
  );
}

