import { useCallback, useEffect, useRef, useState } from 'react';
import { createChart, CandlestickSeries, ColorType, type IChartApi, type ISeriesApi, type UTCTimestamp } from 'lightweight-charts';
import { useDataHub } from '../app/DataHubContext';
import type { PanelProps } from './PanelProps';
import PanelChrome from './PanelChrome';
import { usePanelLink } from './usePanelLink';
import { deriveStreamStatus, usePeriodicCheck, type PanelStatus } from './panelStatus';
import { mergeHistory } from '../core/panels/candles';
import { COLORS } from './colors';
import type { ConnectionStatus } from '../core/hub/protocol';
import type { Candle, KlineInterval } from '../core/types';
import styles from './CandlestickChartPanel.module.css';

const INTERVALS: KlineInterval[] = ['1m', '5m', '15m', '1h', '4h', '1d'];

/**
 * lightweight-charts manages its own internal canvas + render loop, so
 * there's no need to reproduce the ref+rAF pattern used by the ladder/tape
 * panels here. The important rule is the same in spirit though: candle
 * updates are pushed straight into the chart series imperatively (`.update`)
 * from inside the `subscribeCandles` callback - never through React
 * `setState` - so a live-updating in-progress bar doesn't cause a React
 * re-render on every tick across 30 panels.
 */
export default function CandlestickChartPanel({ config, onSymbolChange, onSettingsChange }: PanelProps) {
  const hub = useDataHub();
  const { symbol, linkGroup, handleSymbolChange, handleLinkGroupChange } = usePanelLink(
    config,
    onSymbolChange,
    onSettingsChange,
    'BTCUSDT',
  );

  const initialInterval = (config.settings.interval as KlineInterval | undefined) ?? '1m';
  const [interval, setIntervalState] = useState<KlineInterval>(
    INTERVALS.includes(initialInterval) ? initialInterval : '1m',
  );

  const containerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRef = useRef<ISeriesApi<'Candlestick'> | null>(null);
  const historyRef = useRef<Candle[]>([]);

  const connectionRef = useRef<ConnectionStatus>(hub.getConnectionStatus());
  const lastUpdateRef = useRef<number | null>(null);
  const [status, setStatus] = useState<PanelStatus>('reconnecting');
  const statusRef = useRef<PanelStatus>('reconnecting');

  const recomputeStatus = useCallback(() => {
    const next = deriveStreamStatus(connectionRef.current, lastUpdateRef.current, Date.now());
    if (next !== statusRef.current) {
      statusRef.current = next;
      setStatus(next);
    }
  }, []);

  usePeriodicCheck(recomputeStatus);

  useEffect(() => {
    connectionRef.current = hub.getConnectionStatus();
    recomputeStatus();
    return hub.onConnectionStatus((s) => {
      connectionRef.current = s;
      recomputeStatus();
    });
  }, [hub, recomputeStatus]);

  // Create the chart once per mount; light theme colors throughout.
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const chart = createChart(container, {
      autoSize: true,
      layout: {
        background: { type: ColorType.Solid, color: '#ffffff' },
        textColor: COLORS.textPrimary,
        fontSize: 11,
      },
      grid: {
        vertLines: { color: COLORS.gridLine },
        horzLines: { color: COLORS.gridLine },
      },
      rightPriceScale: { borderColor: COLORS.gridLine },
      timeScale: { borderColor: COLORS.gridLine, timeVisible: true, secondsVisible: false },
    });

    const series = chart.addSeries(CandlestickSeries, {
      upColor: COLORS.bid,
      borderUpColor: COLORS.bid,
      wickUpColor: COLORS.bid,
      downColor: COLORS.ask,
      borderDownColor: COLORS.ask,
      wickDownColor: COLORS.ask,
    });

    chartRef.current = chart;
    seriesRef.current = series;

    return () => {
      chart.remove();
      chartRef.current = null;
      seriesRef.current = null;
    };
  }, []);

  // Re-subscribe whenever symbol or interval changes; a known gap (see final
  // report) is that the hub only streams forward from subscription time with
  // no REST backfill yet, so the chart starts empty and fills in live.
  useEffect(() => {
    historyRef.current = [];
    seriesRef.current?.setData([]);
    lastUpdateRef.current = null;
    recomputeStatus();

    return hub.subscribeCandles(symbol, interval, (candle) => {
      historyRef.current = mergeHistory(historyRef.current, candle);
      seriesRef.current?.update(toChartPoint(candle));
      lastUpdateRef.current = Date.now();
      recomputeStatus();
    });
  }, [hub, symbol, interval, recomputeStatus]);

  const handleIntervalChange = (next: KlineInterval) => {
    setIntervalState(next);
    onSettingsChange({ ...config.settings, interval: next });
  };

  return (
    <PanelChrome
      title="Chart"
      symbol={symbol}
      onSymbolChange={handleSymbolChange}
      linkGroup={linkGroup}
      onLinkGroupChange={handleLinkGroupChange}
      status={status}
    >
      <div className={styles.wrapper}>
        <div className={styles.toolbar}>
          {INTERVALS.map((iv) => (
            <button
              key={iv}
              type="button"
              className={iv === interval ? styles.intervalButtonActive : styles.intervalButton}
              onClick={() => handleIntervalChange(iv)}
            >
              {iv}
            </button>
          ))}
        </div>
        <div ref={containerRef} className={styles.chartArea} />
      </div>
    </PanelChrome>
  );
}

function toChartPoint(candle: Candle) {
  return {
    time: Math.floor(candle.openTime / 1000) as UTCTimestamp,
    open: candle.open,
    high: candle.high,
    low: candle.low,
    close: candle.close,
  };
}

.wrapper {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
}

.toolbar {
  display: flex;
  gap: 2px;
  padding: 4px 6px;
  border-bottom: 1px solid #eef0f3;
  background: #fafbfc;
  flex: 0 0 auto;
}

.intervalButton,
.intervalButtonActive {
  border: 1px solid #d7dbe1;
  background: #ffffff;
  color: #434a5c;
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 4px;
  cursor: pointer;
}

.intervalButton:hover {
  background: #f0f2f5;
}

.intervalButtonActive {
  background: #1f2430;
  color: #ffffff;
  border-color: #1f2430;
}

.chartArea {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useDataHub } from '../app/DataHubContext';
import type { PanelProps } from './PanelProps';
import PanelChrome from './PanelChrome';
import { usePanelLink } from './usePanelLink';
import { deriveStreamStatus, usePeriodicCheck, type PanelStatus } from './panelStatus';
import { sortWatchlist, type WatchlistSortKey } from '../core/panels/watchlist';
import { DEFAULT_WATCHLIST_SYMBOLS } from './registry';
import type { ConnectionStatus } from '../core/hub/protocol';
import type { WatchlistRow } from '../core/types';
import styles from './WatchlistPanel.module.css';

/**
 * Unlike the ladder/tape panels, the mini-ticker stream updates roughly
 * once a second for the whole market rather than at per-tick rate, and this
 * panel renders a handful of table rows (not a dense per-level view) - so
 * plain React state is fine here and keeps row diffing/sorting simple.
 */
export default function WatchlistPanel({ config, onSymbolChange, onSettingsChange }: PanelProps) {
  const hub = useDataHub();
  const { symbol, linkGroup, handleSymbolChange, handleLinkGroupChange } = usePanelLink(
    config,
    onSymbolChange,
    onSettingsChange,
    'BTCUSDT',
  );

  const watchedSymbols = useMemo(
    () => new Set(config.symbols.length > 0 ? config.symbols : DEFAULT_WATCHLIST_SYMBOLS),
    [config.symbols],
  );

  const [rows, setRows] = useState<WatchlistRow[]>([]);
  const [sortBy, setSortBy] = useState<WatchlistSortKey>('changePct');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('desc');

  const connectionRef = useRef<ConnectionStatus>(hub.getConnectionStatus());
  const lastUpdateRef = useRef<number | null>(null);
  const [status, setStatus] = useState<PanelStatus>('reconnecting');
  const statusRef = useRef<PanelStatus>('reconnecting');

  const recomputeStatus = useCallback(() => {
    const next = deriveStreamStatus(connectionRef.current, lastUpdateRef.current, Date.now());
    if (next !== statusRef.current) {
      statusRef.current = next;
      setStatus(next);
    }
  }, []);

  usePeriodicCheck(recomputeStatus);

  useEffect(() => {
    connectionRef.current = hub.getConnectionStatus();
    recomputeStatus();
    return hub.onConnectionStatus((s) => {
      connectionRef.current = s;
      recomputeStatus();
    });
  }, [hub, recomputeStatus]);

  useEffect(() => {
    return hub.subscribeWatchlist((allRows) => {
      setRows(allRows.filter((r) => watchedSymbols.has(r.symbol)));
      lastUpdateRef.current = Date.now();
      recomputeStatus();
    });
  }, [hub, watchedSymbols, recomputeStatus]);

  const sortedRows = useMemo(() => sortWatchlist(rows, sortBy, sortDir), [rows, sortBy, sortDir]);

  const handleSort = (key: WatchlistSortKey) => {
    if (key === sortBy) {
      setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortBy(key);
      setSortDir(key === 'symbol' ? 'asc' : 'desc');
    }
  };

  const sortIndicator = (key: WatchlistSortKey) => (key === sortBy ? (sortDir === 'asc' ? ' ▲' : ' ▼') : '');

  return (
    <PanelChrome
      title="Watchlist"
      symbol={symbol}
      onSymbolChange={handleSymbolChange}
      linkGroup={linkGroup}
      onLinkGroupChange={handleLinkGroupChange}
      status={status}
    >
      <div className={styles.wrapper}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th className={styles.sortable} onClick={() => handleSort('symbol')}>
                Symbol{sortIndicator('symbol')}
              </th>
              <th>Last</th>
              <th className={styles.sortable} onClick={() => handleSort('changePct')}>
                Chg%{sortIndicator('changePct')}
              </th>
              <th>High</th>
              <th>Low</th>
              <th className={styles.sortable} onClick={() => handleSort('quoteVolume')}>
                Quote Vol{sortIndicator('quoteVolume')}
              </th>
            </tr>
          </thead>
          <tbody>
            {sortedRows.length === 0 ? (
              <tr>
                <td className={styles.empty} colSpan={6}>
                  Waiting for watchlist data…
                </td>
              </tr>
            ) : (
              sortedRows.map((row) => (
                <tr
                  key={row.symbol}
                  className={styles.row}
                  onClick={() => handleSymbolChange(row.symbol)}
                  title={`Set link group symbol to ${row.symbol}`}
                >
                  <td className={styles.symbolCell}>{row.symbol}</td>
                  <td className={styles.numCell}>{formatPrice(row.last)}</td>
                  <td className={`${styles.numCell} ${row.changePct >= 0 ? styles.gain : styles.loss}`}>
                    {row.changePct >= 0 ? '+' : ''}
                    {row.changePct.toFixed(2)}%
                  </td>
                  <td className={styles.numCell}>{formatPrice(row.high)}</td>
                  <td className={styles.numCell}>{formatPrice(row.low)}</td>
                  <td className={styles.numCell}>{formatVolume(row.quoteVolume)}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </PanelChrome>
  );
}

function formatPrice(value: number): string {
  if (value >= 1000) return value.toFixed(2);
  if (value >= 1) return value.toFixed(4);
  return value.toFixed(6);
}

function formatVolume(value: number): string {
  if (value >= 1_000_000_000) return `${(value / 1_000_000_000).toFixed(2)}B`;
  if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(2)}M`;
  if (value >= 1_000) return `${(value / 1_000).toFixed(2)}K`;
  return value.toFixed(2);
}

