}

.sortable:hover {
  color: #1f2430;
}

.row {
  cursor: pointer;
}

.row:hover {
  background: #f5f8ff;
}

.row td {
  padding: 5px 8px;
  border-bottom: 1px solid #f0f1f3;
}

.symbolCell {
  text-align: left;
  font-weight: 600;
  color: #1f2430;
}

.numCell {
  text-align: right;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  color: #1f2430;
}

.gain {
  color: #15803d;
  font-weight: 600;
}

